public void testManifestSizeWithMultiplePartitionSpec() throws IOException {
    Assert.assertNull("Table should be empty", table.currentSnapshot());
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    TableMetadata base = readMetadata();
    Assert.assertEquals("Should create 1 manifest for initial write", 1, base.currentSnapshot().allManifests().size());
    ManifestFile initialManifest = base.currentSnapshot().allManifests().get(0);
    int initialPartitionSpecId = initialManifest.partitionSpecId();
    // build the new spec using the table's schema, which uses fresh IDs
    PartitionSpec newSpec = PartitionSpec.builderFor(base.schema()).bucket("data", 16).bucket("id", 4).build();
    // commit the new partition spec to the table manually
    table.ops().commit(base, base.updatePartitionSpec(newSpec));
    DataFile newFileY = DataFiles.builder(newSpec).withPath("/path/to/data-y.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=2/id_bucket=3").withRecordCount(1).build();
    table.newAppend().appendFile(newFileY).commit();
    DataFile newFileZ = DataFiles.builder(newSpec).withPath("/path/to/data-z.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=2/id_bucket=4").withRecordCount(1).build();
    table.newAppend().appendFile(newFileZ).commit();
    Assert.assertEquals("Rewrite manifests should produce 3 manifest files", 3, table.currentSnapshot().allManifests().size());
    // cluster by constant will combine manifests into one but small target size will create one per entry
    BaseRewriteManifests rewriteManifests = spy((BaseRewriteManifests) table.rewriteManifests());
    when(rewriteManifests.getManifestTargetSizeBytes()).thenReturn(1L);
    // rewriteManifests should produce 4 manifestFiles, because of targetByteSize=1
    rewriteManifests.clusterBy(dataFile -> "file").commit();
    List<ManifestFile> manifestFiles = table.currentSnapshot().allManifests();
    Assert.assertEquals("Should use 4 manifest files", 4, manifestFiles.size());
    matchNumberOfManifestFileWithSpecId(manifestFiles, initialPartitionSpecId, 2);
    matchNumberOfManifestFileWithSpecId(manifestFiles, table.ops().current().spec().specId(), 2);
    Assert.assertEquals("first manifest file should have 1 data files", Integer.valueOf(1), manifestFiles.get(0).existingFilesCount());
    Assert.assertEquals("second manifest file should have 1 data files", Integer.valueOf(1), manifestFiles.get(1).existingFilesCount());
    Assert.assertEquals("third manifest file should have 1 data files", Integer.valueOf(1), manifestFiles.get(2).existingFilesCount());
    Assert.assertEquals("fourth manifest file should have 1 data files", Integer.valueOf(1), manifestFiles.get(3).existingFilesCount());
}

